import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom'; // Importar useNavigate
import './Login.css';

function Login() {
  const navigate = useNavigate(); // Inicializar useNavigate
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!email || !password) {
      setError('Por favor ingrese tanto el correo electrónico como la contraseña');
      return;
    }

    try {
      const response = await fetch('http://localhost:4000/api/auth/login', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ email, password }),
      });

      const data = await response.json();

      if (response.ok) {
        localStorage.setItem('token', data.token); 
        console.log('Usuario autenticado:', data.user);

        // Redireccionar según el rol
        if (data.user.id_rol === 1) {
          navigate('/');         // Usuario normal
        } else if (data.user.id_rol === 2) {
          navigate('/admin');    // Admin
        } else {
          navigate('/');         // Rol desconocido, ir al home
        }
      } else {
        setError(data.error);
      }
    } catch (error) {
      console.error('Error en el login:', error);
      setError('Ocurrió un error al intentar iniciar sesión.');
    }
  };

  return (
    <div className="login-container">
      <div className="form-container">
        <div className="login-form">
          <h1>Iniciar sesión</h1>
          <form onSubmit={handleSubmit}>
            <div className="form-group">
              <label>Correo Electrónico</label>
              <input 
                type="email" 
                placeholder="Correo electrónico" 
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required 
              />
            </div>
            <div className="form-group">
              <label>Contraseña</label>
              <input 
                type="password" 
                placeholder="Contraseña" 
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required 
              />
            </div>
            <button type="submit" className="submit-button">Iniciar sesión</button>
          </form>

          {error && <p style={{ color: 'red' }}>{error}</p>}

          <p>¿No tienes cuenta? <a href="/registro" style={{ color: '#dc2626' }}>Regístrate</a></p>
        </div>
      </div>
    </div>
  );
}

export default Login;
